import React, { useState } from 'react';
import './JudgeLogin.css';

const JudgeLogin = ({ onJudgeLogin }) => {
  const [pin, setPin] = useState('');
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState('');

  const handleLogin = async (e) => {
    e.preventDefault();

    if (!pin.trim()) {
      setError('Please enter your PIN');
      return;
    }

    setLoading(true);
    setError('');

    try {
      // Call the judge login API
      const response = await fetch('http://localhost/Tabolator_Casestudy/backend/api/judges/login', {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
        },
        body: JSON.stringify({ pin }),
      });

      const data = await response.json();

      if (data.success) {
        // Login successful
        onJudgeLogin(data.judge);
        setPin('');
      } else {
        setError(data.message || 'Invalid PIN');
      }
    } catch (err) {
      setError('Network error. Please try again.');
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="judge-login-container">
      <div className="judge-login-card">
        <div className="login-header">
          <div className="header-icon">
            <i className="fi fi-rr-user"></i>
          </div>
          <h2>Judge Login</h2>
          <p>Enter your 4-digit PIN to access the scoring system</p>
        </div>

        <form onSubmit={handleLogin} className="login-form">
          <div className="input-group">
            <label htmlFor="pin">Judge PIN:</label>
            <input
              type="password"
              id="pin"
              value={pin}
              onChange={(e) => setPin(e.target.value)}
              placeholder="Enter 4-digit PIN"
              maxLength={4}
              className="pin-input"
              disabled={loading}
              autoFocus
            />
            <button 
              type="submit" 
              className="login-btn"
              disabled={loading || pin.length !== 4}
            >
              {loading ? (
                <>
                  <i className="fi fi-rr-spinner"></i>
                  Logging in...
                </>
              ) : (
                <>
                  <i className="fi fi-rr-sign-in"></i>
                  Login
                </>
              )}
            </button>
          </div>

          {error && (
            <div className="error-message">
              <i className="fi fi-rr-exclamation-triangle"></i>
              {error}
            </div>
          )}
        </form>

        <div className="login-footer">
          <div className="footer-info">
            <i className="fi fi-rr-info"></i>
            <span>Need help? Contact system administrator</span>
          </div>
          <div className="demo-info">
            <i className="fi fi-rr-key"></i>
            <span>Demo PINs: 2847, 9156, 3729, 6481</span>
          </div>
        </div>
      </div>
    </div>
  );
};

export default JudgeLogin;
